/**
 * Calendar-day arithmetic for recurring issues. Days are `YYYY-MM-DD` strings
 * read in a rule's own IANA time zone, so nothing here depends on the zone the
 * server runs in.
 */
import type { RecurringIssue } from "@/types/recurring-issue";

const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;

/** True for a real calendar date written as `YYYY-MM-DD` (rejects 2026-02-30). */
export function isCalendarDate(value: string): boolean {
  if (!DATE_PATTERN.test(value)) return false;
  const [year, month, day] = parseDate(value);
  const date = new Date(0);
  date.setUTCFullYear(year, month - 1, day);
  return (
    date.getUTCFullYear() === year &&
    date.getUTCMonth() === month - 1 &&
    date.getUTCDate() === day
  );
}

/** True when the runtime's Intl knows the zone. Offsets such as `+05:00` are not IANA names. */
export function isKnownTimeZone(value: string): boolean {
  if (value.length === 0 || /^[+-]/.test(value)) return false;
  try {
    new Intl.DateTimeFormat("en-US", { timeZone: value });
    return true;
  } catch {
    return false;
  }
}

/** The calendar day `instant` falls on in `timeZone`, as `YYYY-MM-DD`. */
export function localDateIn(instant: Date, timeZone: string): string {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(instant);

  const part = (type: string): string =>
    parts.find((entry) => entry.type === type)?.value ?? "";

  return `${part("year")}-${part("month")}-${part("day")}`;
}

/** ISO weekday of a `YYYY-MM-DD` day: 1 = Monday … 7 = Sunday. */
export function isoWeekday(date: string): number {
  const [year, month, day] = parseDate(date);
  const weekday = new Date(Date.UTC(year, month - 1, day)).getUTCDay();
  return weekday === 0 ? 7 : weekday;
}

function shiftDate(date: string, days: number): string {
  const [year, month, day] = parseDate(date);
  const value = new Date(0);
  value.setUTCFullYear(year, month - 1, day + days);
  return value.toISOString().slice(0, 10);
}

function parseDate(date: string): readonly [number, number, number] {
  const [year, month, day] = date.split("-").map(Number);
  return [year ?? 0, month ?? 0, day ?? 0];
}

/**
 * The latest occurrence day that has started by `now`, or `null` when none has.
 * A day has started once its local midnight has passed in the rule's zone, which
 * is exactly when the zone's calendar date reaches that day.
 */
export function latestOccurrenceOn(
  rule: Pick<RecurringIssue, "cadence" | "weekday" | "startsOn" | "timezone">,
  now: Date,
): string | null {
  const today = localDateIn(now, rule.timezone);
  if (today < rule.startsOn) return null;

  if (rule.cadence === "daily") return today;

  const weekday = rule.weekday ?? 1;
  const daysBack = (isoWeekday(today) - weekday + 7) % 7;
  const candidate = shiftDate(today, -daysBack);
  return candidate < rule.startsOn ? null : candidate;
}

