import { z } from "zod";
import { isCalendarDate, isKnownTimeZone } from "@/lib/recurrence";
import {
  orgIdSchema,
  projectIdSchema,
  userIdSchema,
} from "./common";
import { issuePrioritySchema } from "./issue";

const recurrenceCadenceSchema = z.enum(["daily", "weekly"]);

export const createRecurringIssueSchema = z
  .object({
    orgId: orgIdSchema,
    projectId: projectIdSchema,
    title: z.string().min(3, "give the recurring issue a title").max(180),
    priority: issuePrioritySchema.default("none"),
    assigneeId: userIdSchema.nullable().default(null),
    cadence: recurrenceCadenceSchema,
    weekday: z.number().int().min(1).max(7).nullable().default(null),
    timezone: z
      .string()
      .refine(isKnownTimeZone, "must be an IANA time zone"),
    startsOn: z
      .string()
      .refine(isCalendarDate, "must be a real YYYY-MM-DD date"),
  })
  .superRefine((input, ctx) => {
    if (input.cadence === "weekly" && input.weekday === null) {
      ctx.addIssue({
        code: "custom",
        path: ["weekday"],
        message: "weekly rules need a weekday",
      });
    }
    if (input.cadence === "daily" && input.weekday !== null) {
      ctx.addIssue({
        code: "custom",
        path: ["weekday"],
        message: "daily rules take no weekday",
      });
    }
  });

export type CreateRecurringIssueInput = z.input<
  typeof createRecurringIssueSchema
>;

