/**
 * Files one issue per due recurring-issue rule, on behalf of the rule's creator.
 *
 * Must call (do not reimplement): can, latestOccurrenceOn, createIssue, requireFound, projectResource
 */
import { createLogger } from "@/lib/logger";
import { can } from "@/lib/permissions";
import { latestOccurrenceOn } from "@/lib/recurrence";
import * as memberRepo from "@/server/repositories/member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as recurringRepo from "@/server/repositories/recurring-issue-repository";
import * as issueService from "@/server/services/issue-service";
import { projectResource, requireFound } from "@/server/services/_support";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { Actor } from "@/types/member";
import type { RecurringIssue } from "@/types/recurring-issue";

const logger = createLogger("recurring-issue-job");

/**
 * Each non-paused rule files at most one issue per run, for its latest started
 * occurrence. Missed occurrences are not back-filled, and a repeat run for the
 * same instant finds `lastOccurrenceOn` already at that day and does nothing.
 */
export async function runRecurringIssueJob(now: Date): Promise<JobResult> {
  return runJob("recurring-issues", async (result) => {
    for (const rule of await recurringRepo.listActiveRecurringIssues()) {
      try {
        const occurrence = latestOccurrenceOn(rule, now);
        if (occurrence === null) continue;
        if (rule.lastOccurrenceOn !== null && occurrence <= rule.lastOccurrenceOn) {
          continue;
        }

        const project = requireFound(
          await projectRepo.findProjectById(rule.orgId, rule.projectId),
          "Project",
          rule.projectId,
        );
        // Archived projects are skipped untouched; the next run after a restore files the then-latest occurrence.
        if (project.archivedAt !== null) continue;

        const actor = await creatorActor(rule);
        if (actor === null || !can(actor, "issue:create", projectResource(project))) {
          await recurringRepo.setRecurringIssuePaused(rule.orgId, rule.id, true);
          logger.warn("recurring issue paused: creator can no longer file", {
            recurringIssueId: rule.id,
          });
          continue;
        }

        await issueService.createIssue(actor, {
          orgId: rule.orgId,
          projectId: rule.projectId,
          title: `${rule.title} (${occurrence})`,
          description: null,
          status: "backlog",
          priority: rule.priority,
          assigneeId: await liveAssignee(rule),
          parentId: null,
          estimate: null,
          dueAt: null,
          labelIds: [],
        });

        await recurringRepo.setLastOccurrenceOn(rule.orgId, rule.id, occurrence);
        result.processed += 1;
      } catch (error) {
        result.failed += 1;
        logger.error("failed to file recurring issue", {
          recurringIssueId: rule.id,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

/** The creator as an actor, with their current role; `null` once they are no longer an active member. */
async function creatorActor(rule: RecurringIssue): Promise<Actor | null> {
  const member = await memberRepo.findMember(rule.orgId, rule.createdBy);
  if (member === null || member.status !== "active") return null;
  return { userId: rule.createdBy, orgId: rule.orgId, role: member.role };
}

/** The rule's assignee if they are still an active member, otherwise unassigned. */
async function liveAssignee(rule: RecurringIssue) {
  if (rule.assigneeId === null) return null;
  const member = await memberRepo.findMember(rule.orgId, rule.assigneeId);
  return member?.status === "active" ? rule.assigneeId : null;
}

